/**
 * 输入法预览页面（无需激活输入法即可测试键盘）。
 *
 * 功能：
 * - 三语切换（柯语/英文/中文拼音）
 * - Shift / Shift Lock
 * - 拼音候选栏
 * - 符号键盘
 * - 九宫格数字键盘（GB/T 31921-2015 标准）
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PreviewScreen() {
    val engine = remember { PreviewEngine() }
    val outputText by remember { engine.outputText }
    val composing by remember { engine.composing }
    val candidates by remember { engine.candidates }

    KyrgyzKeyboardTheme {
        Scaffold(
            topBar = {
                TopAppBar(title = { Text("柯尔克孜语输入法预览") })
            }
        ) { padding ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding)
            ) {
                // 输出文本区（模拟编辑器）
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .padding(16.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(MaterialTheme.colorScheme.surfaceVariant)
                        .padding(16.dp)
                ) {
                    val displayText = outputText + composing
                    if (displayText.isEmpty()) {
                        Text(
                            text = "在此测试键盘输入...",
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                            fontSize = 16.sp
                        )
                    } else {
                        Text(
                            text = displayText,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            fontSize = 18.sp
                        )
                    }
                }

                // 拼音候选栏（仅拼音模式显示）
                if (engine.currentLanguage == Language.PINYIN && candidates.isNotEmpty()) {
                    CandidateBarPreview(
                        composing = composing,
                        candidates = candidates,
                        onPick = { engine.selectCandidate(it) }
                    )
                }

                // 键盘区域
                KeyboardPreview(engine = engine)
            }
        }
    }
}

/**
 * 预览用的键盘引擎包装类。
 * 模拟真实 InputMethodService 的行为，但输出到文本框而非系统编辑器。
 */
class PreviewEngine : KyrgyzKeyboardEngine.Listener {
    private val _outputText = mutableStateOf("")
    val outputText: androidx.compose.runtime.State<String> = _outputText

    private val _composing = mutableStateOf("")
    val composing: androidx.compose.runtime.State<String> = _composing

    private val _candidates = mutableStateOf<List<String>>(emptyList())
    val candidates: androidx.compose.runtime.State<List<String>> = _candidates

    val engine = KyrgyzKeyboardEngine(this)

    val currentLanguage: Language get() = engine.currentLanguage
    val currentLayout: LayoutType get() = engine.currentLayout
    val kyrgyzShift: Boolean get() = engine.kyrgyzShift
    val englishShift: Boolean get() = engine.englishShift
    val shiftLocked: Boolean get() = engine.shiftLocked

    override fun onKeyPress(code: String) {
        _outputText.value = _outputText.value + code
    }

    override fun onKeyAction(action: FunctionType) {
        when (action) {
            FunctionType.BACKSPACE -> {
                if (_composing.value.isNotEmpty()) {
                    // 拼音正在编辑时，先删拼音
                    _composing.value = _composing.value.dropLast(1)
                } else if (_outputText.value.isNotEmpty()) {
                    _outputText.value = _outputText.value.dropLast(1)
                }
            }
            FunctionType.SPACE -> _outputText.value = _outputText.value + " "
            FunctionType.NEWLINE -> _outputText.value = _outputText.value + "\n"
            else -> {}
        }
    }

    override fun onComposingChanged(composing: String) {
        _composing.value = composing
    }

    override fun onCommitCandidate(text: String) {
        _outputText.value = _outputText.value + text
        _composing.value = ""
        _candidates.value = emptyList()
    }

    fun selectCandidate(index: Int) {
        engine.selectCandidate(index)
    }

    fun updateCandidates() {
        // 此方法在引擎内部调用，这里的包装类不需要额外处理
    }
}

@Composable
private fun CandidateBarPreview(
    composing: String,
    candidates: List<String>,
    onPick: (Int) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(44.dp)
            .clip(RoundedCornerShape(6.dp))
            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f))
    ) {
        val scroll = rememberScrollState()
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .horizontalScroll(scroll)
                .padding(horizontal = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (composing.isNotEmpty()) {
                Text(
                    text = composing,
                    color = MaterialTheme.colorScheme.primary,
                    fontSize = 14.sp,
                    modifier = Modifier.padding(end = 12.dp)
                )
            }
            candidates.forEachIndexed { i, cand ->
                Box(
                    modifier = Modifier
                        .padding(horizontal = 4.dp)
                        .clip(RoundedCornerShape(4.dp))
                        .clickable { onPick(i) }
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = cand,
                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                        fontSize = 20.sp
                    )
                }
            }
        }
    }
}

@Composable
private fun KeyboardPreview(engine: PreviewEngine) {
    val rows = remember(engine.currentLanguage, engine.currentLayout, engine.kyrgyzShift, engine.englishShift) {
        engine.engine.getRows()
    }
    val isRtl = engine.currentLanguage == Language.KYRGYZ
    val direction = if (isRtl) LayoutDirection.Rtl else LayoutDirection.Ltr

    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Surface(
            color = MaterialTheme.colorScheme.surface,
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(4.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                val onKey: (KyrgyzKey) -> Unit = remember(engine) {
                    { k -> engine.engine.handleKey(k) }
                }
                val onVariant: (String) -> Unit = remember(engine) {
                    { v -> engine.engine.handleVariant(v) }
                }
                rows.forEachIndexed { rowIndex, row ->
                    key(engine.currentLanguage, engine.currentLayout, engine.kyrgyzShift, engine.englishShift, rowIndex) {
                        KeyboardRowPreview(
                            row = row,
                            onKey = onKey,
                            onVariant = onVariant,
                            shiftActive = if (engine.currentLanguage == Language.KYRGYZ) engine.kyrgyzShift else engine.englishShift,
                            shiftLocked = engine.shiftLocked
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun KeyboardRowPreview(
    row: KeyboardRow,
    onKey: (KyrgyzKey) -> Unit,
    onVariant: (String) -> Unit,
    shiftActive: Boolean,
    shiftLocked: Boolean
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(52.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        row.keys.forEachIndexed { index, k ->
            key(index, k.code, k.function) {
                KeyViewPreview(
                    keyData = k,
                    modifier = Modifier.weight(k.weight),
                    onKey = onKey,
                    onVariant = onVariant,
                    shiftActive = shiftActive,
                    shiftLocked = shiftLocked
                )
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun KeyViewPreview(
    keyData: KyrgyzKey,
    modifier: Modifier = Modifier,
    onKey: (KyrgyzKey) -> Unit,
    onVariant: (String) -> Unit,
    shiftActive: Boolean,
    shiftLocked: Boolean
) {
    val isShift = keyData.function == FunctionType.SHIFT
    val isDigital = keyData.type == KeyType.DIGITAL

    // 数字键有特殊样式
    if (isDigital) {
        DigitalKeyPreview(
            keyData = keyData,
            modifier = modifier,
            onKey = onKey,
            onVariant = onVariant
        )
        return
    }

    val bg = when {
        isShift && shiftLocked -> MaterialTheme.colorScheme.primary
        isShift && shiftActive -> MaterialTheme.colorScheme.primary.copy(alpha = 0.7f)
        keyData.type == KeyType.FUNCTION -> MaterialTheme.colorScheme.secondaryContainer
        keyData.type == KeyType.SYMBOL -> MaterialTheme.colorScheme.surfaceVariant
        keyData.type == KeyType.LETTER -> MaterialTheme.colorScheme.primaryContainer
        else -> MaterialTheme.colorScheme.primaryContainer
    }
    val fg = when {
        isShift && (shiftActive || shiftLocked) -> MaterialTheme.colorScheme.onPrimary
        keyData.type == KeyType.FUNCTION -> MaterialTheme.colorScheme.onSecondaryContainer
        keyData.type == KeyType.SYMBOL -> MaterialTheme.colorScheme.onSurfaceVariant
        keyData.type == KeyType.LETTER -> MaterialTheme.colorScheme.onPrimaryContainer
        else -> MaterialTheme.colorScheme.onPrimaryContainer
    }
    val weight = if (isShift && shiftLocked) FontWeight.Bold else FontWeight.Normal
    val hasVariants = keyData.variants.isNotEmpty()
    val clickModifier = if (hasVariants) {
        Modifier.combinedClickable(
            onClick = { onKey(keyData) },
            onLongClick = { keyData.variants.firstOrNull()?.let(onVariant) }
        )
    } else {
        Modifier.clickable { onKey(keyData) }
    }
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(8.dp))
            .background(bg)
            .then(clickModifier),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = keyData.label,
            color = fg,
            fontSize = 20.sp,
            fontWeight = weight,
            textAlign = TextAlign.Center
        )
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun DigitalKeyPreview(
    keyData: KyrgyzKey,
    modifier: Modifier = Modifier,
    onKey: (KyrgyzKey) -> Unit,
    onVariant: (String) -> Unit
) {
    val hasVariants = keyData.variants.isNotEmpty() && keyData.variants.size > 1
    val clickModifier = if (hasVariants) {
        Modifier.combinedClickable(
            onClick = { onKey(keyData) },
            onLongClick = { keyData.variants.firstOrNull()?.let(onVariant) }
        )
    } else {
        Modifier.clickable { onKey(keyData) }
    }

    Box(
        modifier = modifier
            .clip(RoundedCornerShape(8.dp))
            .background(MaterialTheme.colorScheme.tertiaryContainer)
            .then(clickModifier)
    ) {
        // 数字标签（右上角）
        Text(
            text = keyData.label,
            color = MaterialTheme.colorScheme.onTertiaryContainer.copy(alpha = 0.6f),
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            modifier = Modifier
                .align(Alignment.TopEnd)
                .padding(top = 2.dp, end = 4.dp)
        )

        // 字母提示（中间）
        if (keyData.variants.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .align(Alignment.Center)
                    .padding(top = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(2.dp)
            ) {
                keyData.variants.take(4).forEach { char ->
                    Text(
                        text = char,
                        color = MaterialTheme.colorScheme.onTertiaryContainer,
                        fontSize = 16.sp,
                        textAlign = TextAlign.Center
                    )
                }
            }
        }
    }
}